package com.turboio.androidtests;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import java.lang.reflect.*;import java.time.*;import java.util.*;import java.util.concurrent.atomic.*;import java.util.function.Consumer;
/** Installed production scroll view, synthetic dates only; no material changes or requests. */
public final class WeekStripProbe extends Instrumentation {
 private Activity activity;private View strip;private Dialog dialog;private int checks;private final AtomicInteger callbacks=new AtomicInteger();private final List<Integer> samples=new ArrayList<>();private LocalDate chosen,pickedDay;private final AtomicInteger picks=new AtomicInteger();
 public void onCreate(Bundle args){super.onCreate(args);start();}
 private void check(boolean value){checks++;if(!value)throw new AssertionError("WEEK_STRIP_CHECK_"+checks);}
 private void create()throws Exception{runOnMainSync(()->{try{if(dialog!=null)dialog.dismiss();callbacks.set(0);picks.set(0);Class<?> c=activity.getClassLoader().loadClass("com.turboio.addon.MaterialWeekStrip");Constructor<?> ctor=c.getDeclaredConstructor(Activity.class,LocalDate.class,LocalDate.class,Set.class,Consumer.class,Consumer.class,Runnable.class);ctor.setAccessible(true);strip=(View)ctor.newInstance(activity,LocalDate.of(2026,10,26),LocalDate.of(2026,10,26),Collections.emptySet(),(Consumer<LocalDate>)day->{pickedDay=day;picks.incrementAndGet();},(Consumer<LocalDate>)day->{chosen=day;callbacks.incrementAndGet();},(Runnable)()->{});dialog=new Dialog(activity);dialog.setContentView(strip,new ViewGroup.LayoutParams(-1,-1));dialog.show();dialog.getWindow().setLayout(1000,240);}catch(Exception e){throw new RuntimeException(e);}});Thread.sleep(300);}
 private void send(long down,int action,float x){runOnMainSync(()->{MotionEvent e=MotionEvent.obtain(down,SystemClock.uptimeMillis(),action,x,90,0);strip.dispatchTouchEvent(e);e.recycle();samples.add(strip.getScrollX());});}
 private View find(View view,LocalDate day){if(day.equals(view.getTag()))return view;if(view instanceof ViewGroup)for(int i=0;i<((ViewGroup)view).getChildCount();i++){View found=find(((ViewGroup)view).getChildAt(i),day);if(found!=null)return found;}return null;}
 private int x(){int[] result={0};runOnMainSync(()->result[0]=strip.getScrollX());return result[0];}
 public void onStart(){Bundle out=new Bundle();try{Context app=getTargetContext();activity=startActivitySync(new Intent().setClassName(app,"com.rayneo.venus.MainActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));create();int baseline=x();out.putInt("viewport_width",strip.getWidth());out.putInt("initial_scroll",baseline);check(baseline>0);long down=SystemClock.uptimeMillis();send(down,0,850);for(int i=1;i<=12;i++){Thread.sleep(24);send(down,2,850-i*50);}check(callbacks.get()==0);check(x()>baseline+450);send(down,1,250);Set<Integer> releaseFrames=new HashSet<>();for(int i=0;i<120&&callbacks.get()==0;i++){Thread.sleep(16);releaseFrames.add(x());}check(callbacks.get()==1);check(LocalDate.of(2026,10,26).plusWeeks(1).equals(chosen));out.putInt("distinct_release_positions",releaseFrames.size());out.putString("release_positions",releaseFrames.toString());check(releaseFrames.size()>3);out.putInt("distinct_drag_positions",new HashSet<>(samples).size());check(picks.get()==0);check(x()==baseline);out.putBoolean("swipe_and_settle_do_not_select_day",true);
  LocalDate firstWeek=chosen;for(int pass=0;pass<4;pass++){LocalDate previous=chosen;int expected=callbacks.get()+1;long next=SystemClock.uptimeMillis();send(next,0,850);for(int i=1;i<=10;i++){Thread.sleep(24);send(next,2,850-i*55);}send(next,1,300);for(int i=0;i<100&&callbacks.get()<expected;i++)Thread.sleep(16);check(callbacks.get()==expected&&picks.get()==0&&x()==baseline&&previous.plusWeeks(1).equals(chosen));}check(chosen.isAfter(firstWeek.plusWeeks(2)));out.putBoolean("repeat_browse_recycles_without_selecting",true);
  LocalDate tapped=chosen.plusDays(2);float[] target={0,0};runOnMainSync(()->{View day=find(strip,tapped);check(day!=null);int[] child=new int[2],parent=new int[2];day.getLocationInWindow(child);strip.getLocationInWindow(parent);target[0]=child[0]-parent[0]+day.getWidth()/2f;target[1]=child[1]-parent[1]+day.getHeight()/2f;});long tapTime=SystemClock.uptimeMillis();for(int action:new int[]{0,1}){runOnMainSync(()->{MotionEvent e=MotionEvent.obtain(tapTime,SystemClock.uptimeMillis(),action,target[0],target[1],0);strip.dispatchTouchEvent(e);e.recycle();});Thread.sleep(48);}for(int i=0;i<30&&picks.get()==0;i++)Thread.sleep(16);check(picks.get()==1&&tapped.equals(pickedDay));out.putBoolean("only_explicit_day_click_selects",true);
  for(int direction:new int[]{1,-1}){create();long fast=SystemClock.uptimeMillis();send(fast,0,direction>0?880:40);for(int i=1;i<=6;i++){Thread.sleep(6);send(fast,2,direction>0?880-i*130:40+i*130);}send(fast,1,direction>0?100:820);for(int i=0;i<120&&callbacks.get()==0;i++)Thread.sleep(16);check(callbacks.get()==1&&LocalDate.of(2026,10,26).plusWeeks(direction).equals(chosen)&&picks.get()==0);}out.putBoolean("large_fast_swipes_max_one_week_both_directions",true);
  create();callbacks.set(0);baseline=x();down=SystemClock.uptimeMillis();send(down,0,850);for(int i=1;i<=8;i++){Thread.sleep(24);send(down,2,850-i*45);}send(down,3,490);Thread.sleep(800);check(callbacks.get()==0);check(x()==baseline);out.putBoolean("cancel_returns_without_selecting",true);
  create();callbacks.set(0);baseline=x();down=SystemClock.uptimeMillis();send(down,0,850);for(int i=1;i<=8;i++){Thread.sleep(24);send(down,2,850-i*45);}send(down,1,490);Thread.sleep(32);long reverse=SystemClock.uptimeMillis();runOnMainSync(()->{int before=strip.getScrollX();MotionEvent e=MotionEvent.obtain(reverse,reverse,0,250,90,0);strip.dispatchTouchEvent(e);e.recycle();check(strip.getScrollX()==before);});for(int i=1;i<=6;i++){Thread.sleep(24);send(reverse,2,250+i*45);}send(reverse,3,520);Thread.sleep(800);check(callbacks.get()==0&&x()==baseline);out.putBoolean("reverse_drag_interrupts_fling_without_jump",true);
  create();callbacks.set(0);down=SystemClock.uptimeMillis();send(down,0,850);for(int i=1;i<=8;i++){Thread.sleep(24);send(down,2,850-i*45);}send(down,1,490);Thread.sleep(32);runOnMainSync(()->dialog.dismiss());Thread.sleep(500);check(callbacks.get()==0);out.putBoolean("detached_animation_cannot_select",true);out.putBoolean("passed",true);out.putInt("checks",checks);
 }catch(Throwable e){while(e.getCause()!=null)e=e.getCause();out.putBoolean("passed",false);String msg=e.getMessage();out.putString("error",msg!=null&&msg.matches("[A-Z_0-9]{3,80}")?msg:e.getClass().getSimpleName());}finally{runOnMainSync(()->{if(dialog!=null)dialog.dismiss();});finish(Activity.RESULT_OK,out);}}
}
